    extension: { title: "从一片麦田看见劳动和责任", text: "《观刈麦》没有只写金黄的丰收，而是把脚下土热、背上日灼、贫妇破筐和税尽无粮都放进同一片田野。读到最后，诗人的自愧提醒我们：看见劳动者，不能只看结果，还要理解他们付出的时间、身体和生活代价。", prompt: "当你享用一件东西时，你愿意去了解它经过了哪些人的劳动吗？你最想先了解什么？" },
